(select name as results from MovieRating mr join Users u on mr.user_id=u.user_id group by u.user_id order by count(u.user_id) desc,name asc limit 1) union all
(select title as results from MovieRating mr join Movies m on mr.movie_id=m.movie_id where mr.created_at>='2020-02-01' and mr.created_at<='2020-02-29' group by mr.movie_id order by avg(mr.rating) desc,title asc limit 1);